// 1. 门面模式基础结构
public class SubSystemA {
    public void operationA() {
        System.out.println("子系统A的操作");
    }
}
public class SubSystemB {
    public void operationB() {
        System.out.println("子系统B的操作");
    }
}
public class SubSystemC {
    public void operationC() {
        System.out.println("子系统C的操作");
    }
}
public class Facade {
    private SubSystemA a = new SubSystemA();
    private SubSystemB b = new SubSystemB();
    private SubSystemC c = new SubSystemC();

    public void operation() {
        a.operationA();
        b.operationB();
        c.operationC();
    }
}

// 2. SLF4J 门面模式
// SLF4J 是日志门面，底层绑定可以是 Logback、Log4j 等
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
Logger logger = LoggerFactory.getLogger(MyClass.class);
logger.info("Hello SLF4J");

// 3. MyBatis SqlSession 门面
// SqlSession 封装 Executor/StatementHandler/ParameterHandler/ResultSetHandler 一整条链
SqlSession session = sqlSessionFactory.openSession();
try {
    UserMapper mapper = session.getMapper(UserMapper.class);
    User user = mapper.selectById(1L);
} finally {
    session.close();
}

// 4. 自定义门面：订单处理门面
public class OrderFacade {
    private InventoryService inventory;
    private PaymentService payment;
    private ShippingService shipping;

    public void placeOrder(Order order) {
        inventory.checkStock(order);
        payment.processPayment(order);
        shipping.scheduleDelivery(order);
    }
}
